#include <vector>
using namespace std;

class Solution {
public:
    int addRungs(vector<int>& rungs, int dist) {
        int prev = 0, res = 0;
        for (int r : rungs) {
            if (r - prev > dist)
                res += (r - prev - 1) / dist;
            prev = r;
        }
        return res;
    }
};
